import { LEGAL_TRANSLATION_REVIEW_STATUS } from './legal-metadata.js';
import type {
  LegalBlock,
  LegalDocumentDefinition,
  LegalPageId,
  LegalSection
} from './legal-content.js';
import type { SupportedLocale } from './localization.js';

type TranslatedLocale = Exclude<SupportedLocale, 'en'>;

const paragraph = (text: string): LegalBlock => Object.freeze({
  kind: 'paragraph',
  text: text.replaceAll('\\n', '\n')
});

/**
 * Localized legal pages keep complete section bodies together so line breaks
 * and bullet markers remain readable without creating a second legal authority.
 */
const translatedSection = (
  number: string,
  heading: string,
  text: string
): LegalSection => Object.freeze({
  number,
  heading,
  blocks: Object.freeze([paragraph(text)])
});

const translatedDocument = (
  page: LegalPageId,
  locale: TranslatedLocale,
  title: string,
  description: string,
  effectiveDate: string,
  introduction: readonly string[],
  sections: readonly LegalSection[],
  canonicalSourceId: string
): LegalDocumentDefinition => Object.freeze({
  page,
  locale,
  title,
  description,
  effectiveDate,
  introduction: Object.freeze(introduction),
  sections: Object.freeze(sections),
  canonicalSourceId,
  translationOf: canonicalSourceId,
  translationReviewStatus: LEGAL_TRANSLATION_REVIEW_STATUS
});

const PRIVACY_SOURCE = 'NATALNODE_PRIVACY_POLICY_V1';
const TERMS_SOURCE = 'NATALNODE_TERMS_OF_SERVICE_V1';

const esPrivacy = translatedDocument(
  'privacy',
  'es',
  'Política de privacidad',
  'Esta Política de privacidad explica qué información personal recopila NatalNode, por qué se procesa, cómo se utiliza y divulga, durante cuánto tiempo puede conservarse y qué opciones y derechos tienes.',
  '[EFFECTIVE_DATE]',
  [
    'NatalNode ofrece herramientas de creación de cartas astrológicas, educativas, informativas e interpretativas a través de natalnode.com y servicios relacionados (el «Servicio»).',
    'Esta Política de privacidad explica qué información personal recopila NatalNode, por qué se procesa, cómo se utiliza y divulga, durante cuánto tiempo puede conservarse y qué opciones y derechos tienes.',
    'A efectos de la legislación aplicable sobre protección de datos, el operador identificado a continuación es el responsable del tratamiento o la empresa responsable de la información personal procesada a través del Servicio.',
    'Operador: [OPERATOR_LEGAL_NAME]\\nDomicilio registrado: [OPERATOR_ADDRESS]\\nContacto de privacidad: [PRIVACY_CONTACT_EMAIL]',
    'Estos datos del operador deben completarse antes del lanzamiento comercial público.'
  ],
  [
    translatedSection('1', 'Información que recopilamos', "1.1 Información de la cuenta\\n\\nSi creas o utilizas una cuenta, podemos procesar información como:\\n\\n• dirección de correo electrónico;\\n• identificadores de autenticación;\\n• estado de la cuenta;\\n• registros de autenticación y seguridad;\\n• preferencias y ajustes de la cuenta.\\n\\nCuando se ofrezca el inicio de sesión de terceros, recibiremos únicamente la información necesaria para autenticar u operar la cuenta, según lo permita ese proveedor y tus ajustes.\\n\\n1.2 Información de nacimiento y de la carta\\n\\nPara proporcionar funciones relacionadas con cartas, puedes facilitar información que incluya:\\n\\n• fecha de nacimiento;\\n• hora de nacimiento, cuando se conozca;\\n• lugar de nacimiento o consulta de ubicación;\\n• lugar de nacimiento canónico seleccionado;\\n• coordenadas geográficas derivadas de la ubicación seleccionada;\\n• identidad de zona horaria IANA;\\n• información de resolución temporal necesaria para establecer el instante pertinente;\\n• opciones de configuración de la carta;\\n• datos de la carta resultante e interpretaciones relacionadas.\\n\\nNatalNode trata la información de nacimiento y de la carta como información del producto sensible desde el punto de vista de la privacidad, aunque una ley concreta no clasifique cada componente como información personal legalmente sensible.\\n\\nSi se desconoce la hora de nacimiento, NatalNode puede conservar ese estado como desconocido en lugar de inventar una hora sustitutiva.\\n\\n1.3 Cartas guardadas e información de Vault\\n\\nSi eliges guardar cartas o material relacionado en un Vault o función de cuenta similar, podemos almacenar:\\n\\n• datos de entrada de la carta;\\n• resultados de la carta;\\n• etiquetas o nombres que asignes;\\n• notas o ajustes asociados;\\n• marcas de tiempo y relaciones con la cuenta necesarias para operar la función guardada.\\n\\nGuardar información es distinto de introducirla únicamente para un cálculo cuando la arquitectura del producto permite un uso transitorio.\\n\\n1.4 Información sobre otras personas\\n\\nEl Servicio puede permitirte introducir información relativa a otra persona, por ejemplo al crear o comparar cartas.\\n\\nEres responsable de asegurarte de que tienes una base jurídica adecuada o permiso para proporcionar información personal de otra persona a NatalNode.\\n\\nNo debes enviar información sobre otra persona cuando no tengas un motivo legítimo o la autoridad adecuada para hacerlo.\\n\\n1.5 Envíos de la comunidad, de profesionales, de comentarios y otros\\n\\nCuando estas funciones estén disponibles, podemos procesar información que envíes voluntariamente mediante:\\n\\n• preguntas o debates de la comunidad;\\n• perfiles o solicitudes de profesionales;\\n• procesos de moderación;\\n• formularios de comentarios;\\n• comunicaciones de soporte;\\n• informes u otros envíos generados por usuarios.\\n\\nLos envíos públicos pueden ser visibles para otros usuarios según indique la función correspondiente.\\n\\n1.6 Información técnica y de seguridad\\n\\nCuando utilizas el Servicio, los servidores y sistemas de seguridad pueden procesar automáticamente información como:\\n\\n• dirección IP;\\n• marcas de tiempo de las solicitudes;\\n• información del navegador y del dispositivo;\\n• información del sistema operativo;\\n• rutas solicitadas;\\n• eventos de sesión y autenticación;\\n• eventos de seguridad;\\n• información de diagnóstico y errores;\\n• información aproximada de red o región cuando sea necesaria para la seguridad o la prestación del Servicio.\\n\\nNatalNode no requiere una geolocalización precisa del dispositivo simplemente para inferir tu lugar de nacimiento. La autoridad sobre el lugar de nacimiento se establece mediante la introducción explícita de la ubicación y la selección de un candidato.\\n\\n1.7 Cookies y tecnologías similares\\n\\nNatalNode puede utilizar cookies o tecnologías locales equivalentes necesarias para:\\n\\n• mantener sesiones de autenticación;\\n• preservar la seguridad;\\n• prevenir abusos;\\n• recordar preferencias esenciales;\\n• proporcionar funciones básicas del Servicio.\\n\\nNo se introducirán tecnologías no esenciales de análisis, publicidad o seguimiento entre sitios sin las divulgaciones y controles exigidos por la legislación aplicable."),
    translatedSection('2', 'Cómo utilizamos la información personal', "Podemos procesar información personal para:\\n\\n• proporcionar las funciones de creación de cartas y del Servicio solicitadas;\\n• resolver lugares introducidos por usuarios en ubicaciones canónicas;\\n• establecer la información temporal necesaria para los cálculos de cartas solicitados;\\n• crear y gestionar cuentas;\\n• operar funciones de cartas guardadas y Vault;\\n• proporcionar funciones de comunidad, profesionales, comentarios o soporte;\\n• autenticar usuarios y mantener sesiones;\\n• proteger el Servicio y detectar fraude, abuso, ataques o fallos técnicos;\\n• diagnosticar y mejorar la fiabilidad, accesibilidad y rendimiento;\\n• comunicarnos contigo sobre tu cuenta o el Servicio;\\n• cumplir obligaciones legales y hacer cumplir nuestras Condiciones;\\n• proteger los derechos, la seguridad y la integridad de los usuarios, NatalNode y otras personas.\\n\\nNatalNode no utiliza información personal de nacimiento para fabricar hechos astronómicos cuando no están disponibles entradas de cálculo o servicios autorizados."),
    translatedSection('3', 'Bases jurídicas del tratamiento', "Cuando leyes como el RGPD exigen una base jurídica, NatalNode se basa, según corresponda, en:\\n\\nEjecución de un contrato o medidas solicitadas por ti: por ejemplo, proporcionar una cuenta, generar una carta solicitada, resolver una ubicación solicitada o conservar contenido que elijas guardar.\\n\\nIntereses legítimos: por ejemplo, operar y proteger el Servicio, detectar abusos, depurar fallos, mantener la seguridad de la red y de la información y mejorar la fiabilidad cuando esos intereses no prevalezcan sobre tus derechos.\\n\\nConsentimiento: cuando el consentimiento sea legalmente exigible, incluso para comunicaciones opcionales o tecnologías no esenciales.\\n\\nObligaciones legales: cuando el tratamiento sea necesario para cumplir la legislación aplicable, procesos legales válidos, requisitos contables o deberes regulatorios."),
    translatedSection('4', 'Resolución de ubicaciones y GeoNames', "NatalNode puede utilizar GeoNames u otro proveedor aprobado de información de ubicaciones para ayudar a convertir búsquedas de lugares en candidatos de ubicación estructurados.\\n\\nLa información de resolución de ubicaciones puede incluir:\\n\\n• la consulta de lugar que envíes;\\n• nombre canónico del lugar;\\n• información del país y de la región administrativa;\\n• latitud y longitud;\\n• identidad de la zona horaria;\\n• identificadores de registros del proveedor.\\n\\nNatalNode exige una selección explícita cuando existen varias ubicaciones plausibles y no trata el texto sin procesar del usuario como identidad de ubicación autorizada.\\n\\nLos datos y servicios web de GeoNames se proporcionan bajo una licencia de atribución y GeoNames describe sus datos como proporcionados «tal cual». Por ello, NatalNode mantiene la atribución del proveedor cuando corresponde.\\n\\nUn proveedor de ubicaciones establece la identidad del lugar y los metadatos geográficos relacionados. Por sí solo no establece desplazamientos históricos autorizados de la hora de nacimiento ni hechos astronómicos de una carta."),
    translatedSection('5', 'Proveedores de astronomía y servicios técnicos', "NatalNode puede utilizar proveedores externos autorizados de infraestructura, datos, comunicaciones, alojamiento, bases de datos, seguridad, correo electrónico y servicios relacionados con la astronomía cuando sea necesario para operar el Servicio.\\n\\nNatalNode procura limitar los datos divulgados a los proveedores de servicios a la información razonablemente necesaria para su función.\\n\\nEl proveedor de astronomía de producción contará con autorización comercial antes de que se lancen las funciones de producción pertinentes.\\n\\nPuede mantenerse por separado una lista actual de servicios externos materiales o subencargados y actualizarse cuando cambien los proveedores.\\n\\nCambiar un proveedor de infraestructura o de astronomía no autoriza a NatalNode a utilizar tu información para una finalidad no relacionada."),
    translatedSection('6', 'Cómo divulgamos la información personal', "NatalNode puede divulgar información personal a las siguientes categorías de destinatarios cuando sea necesario:\\n\\nProveedores de servicios\\n\\nEmpresas que proporcionan servicios de infraestructura u operación, como:\\n\\n• alojamiento;\\n• bases de datos;\\n• autenticación;\\n• envío de correo electrónico;\\n• seguridad;\\n• diagnóstico;\\n• resolución de ubicaciones;\\n• infraestructura de datos astronómicos autorizada;\\n• procesamiento de pagos si se ofrecen productos de pago.\\n\\nReciben información únicamente para la finalidad operativa pertinente y están sujetos a obligaciones contractuales o legales aplicables.\\n\\nOtros usuarios\\n\\nLa información solo se divulga a otros usuarios cuando utilizas intencionadamente una función pública o colaborativa, como contenido público de la comunidad o un perfil público de profesional.\\n\\nLa información privada del Vault no se hace pública simplemente por estar guardada.\\n\\nDivulgaciones legales y de seguridad\\n\\nLa información puede divulgarse cuando sea razonablemente necesario para:\\n\\n• cumplir la legislación aplicable o un proceso legal válido;\\n• responder a solicitudes gubernamentales lícitas;\\n• investigar fraude o abuso;\\n• proteger la seguridad del Servicio;\\n• proteger derechos legales o la seguridad.\\n\\nTransferencias empresariales\\n\\nSi NatalNode, o sustancialmente todos los activos pertinentes, se reorganiza, financia, adquiere, fusiona, transfiere o vende, la información personal puede transferirse como parte de esa operación, sujeta a la legislación aplicable y a protecciones adecuadas.\\n\\nSi el Servicio pasa de una estructura de desarrollo individual mantenida por el fundador a una entidad operativa posterior, las notificaciones y la información del responsable exigidas se actualizarán antes o cuando lo exija dicha transición."),
    translatedSection('7', 'Venta y uso publicitario de la información personal', "NatalNode no vende información personal a cambio de dinero.\\n\\nNatalNode no utiliza información de nacimiento o de cartas para publicidad comportamental entre contextos de terceros.\\n\\nSi NatalNode introduce posteriormente publicidad o prácticas de datos que constituyan «venta», «intercambio» o publicidad dirigida conforme a la legislación de privacidad aplicable, esas prácticas no comenzarán sin actualizar el aviso correspondiente y proporcionar los controles de consentimiento o exclusión exigidos."),
    translatedSection('8', 'Conservación de datos', "NatalNode conserva la información personal únicamente durante el tiempo razonablemente necesario para la finalidad para la que se recopiló, incluyendo:\\n\\n• operar una cuenta activa;\\n• mantener información que hayas decidido guardar;\\n• proporcionar los servicios solicitados;\\n• mantener registros de seguridad y prevención de abusos;\\n• resolver disputas;\\n• hacer cumplir acuerdos;\\n• cumplir obligaciones legales, contables o regulatorias.\\n\\nCuando se elimina una cuenta o un elemento guardado, la información asociada se eliminará o desidentificará conforme al proceso de eliminación aplicable, sujeta a requisitos legítimos de conservación de copias de seguridad, seguridad, prevención de fraude, legales o de cumplimiento.\\n\\nLas copias de seguridad pueden conservar información durante un periodo limitado hasta que se complete la rotación normal.\\n\\nNatalNode mantendrá un calendario interno de conservación adecuado para la arquitectura de producción, en lugar de conservar información indefinidamente sin una finalidad."),
    translatedSection('9', 'Transferencias internacionales de datos', "NatalNode está concebido como un servicio internacional y su infraestructura o sus proveedores pueden operar en países distintos de aquel en el que vives.\\n\\nCuando la legislación aplicable exija garantías para las transferencias internacionales, NatalNode utilizará mecanismos legalmente reconocidos adecuados para la transferencia, como:\\n\\n• decisiones de adecuación;\\n• garantías contractuales;\\n• cláusulas contractuales tipo aprobadas;\\n• otros mecanismos legales de transferencia.\\n\\nLas regiones de alojamiento de producción concretas y los subencargados pertinentes deben revisarse antes del lanzamiento."),
    translatedSection('10', 'Tus derechos de privacidad', "Dependiendo de dónde vivas y de la legislación aplicable, puedes tener derecho a:\\n\\n• solicitar acceso a la información personal;\\n• obtener información sobre su tratamiento;\\n• corregir información inexacta;\\n• solicitar su eliminación;\\n• restringir determinados tratamientos;\\n• oponerte a determinados tratamientos;\\n• recibir determinada información en un formato portable;\\n• retirar el consentimiento cuando el tratamiento se base en el consentimiento;\\n• excluirte de determinadas prácticas de venta, intercambio o publicidad dirigida cuando corresponda;\\n• apelar determinadas decisiones de privacidad cuando corresponda;\\n• presentar una reclamación ante una autoridad de protección de datos adecuada.\\n\\nPara ejercer un derecho de privacidad aplicable, contacta con:\\n\\n[PRIVACY_CONTACT_EMAIL]\\n\\nNatalNode puede necesitar verificar tu identidad antes de atender determinadas solicitudes y utilizará la información de verificación únicamente según corresponda para ese proceso.\\n\\nNo te discriminaremos ilegalmente por ejercer derechos de privacidad aplicables."),
    translatedSection('11', 'Seguridad', "NatalNode utilizará medidas técnicas y organizativas razonables diseñadas para proteger la información personal frente a:\\n\\n• acceso no autorizado;\\n• divulgación no autorizada;\\n• alteración;\\n• pérdida accidental;\\n• destrucción;\\n• uso indebido.\\n\\nLas medidas de seguridad serán proporcionales a la naturaleza de la información y a la arquitectura de producción.\\n\\nNingún sistema, mecanismo de almacenamiento, transmisión de red o servicio en línea puede garantizar una seguridad absoluta."),
    translatedSection('12', 'Menores', "NatalNode no está dirigido a menores de 13 años.\\n\\nDebes tener al menos 13 años para utilizar el Servicio.\\n\\nCuando la legislación aplicable exija una edad superior para que una persona pueda consentir de forma independiente al tratamiento de información personal o al uso de un servicio en línea, se aplicará esa edad mínima superior.\\n\\nNatalNode no busca conscientemente recopilar información personal de menores de 13 años. Si descubrimos que dicha información se ha recopilado en contra de los requisitos aplicables, tomaremos medidas adecuadas para eliminarla o abordarla de otro modo."),
    translatedSection('13', 'Resultados automatizados e interpretativos', "NatalNode puede generar o presentar interpretaciones astrológicas basadas en información estructurada de cartas.\\n\\nEsa interpretación no significa que NatalNode tome decisiones legalmente significativas sobre ti.\\n\\nNatalNode no utiliza la interpretación astrológica para determinar la elegibilidad para empleo, crédito, vivienda, seguros, atención sanitaria, educación u otras decisiones similares de alto impacto.\\n\\nSi en el futuro se introduce una toma de decisiones automatizada materialmente distinta, esta Política se actualizará como corresponda antes de que comience ese uso."),
    translatedSection('14', 'Cambios en esta Política de privacidad', "NatalNode puede actualizar esta Política cuando cambien el Servicio, la legislación, la infraestructura o las prácticas de datos.\\n\\nLos cambios materiales se comunicarán de una manera adecuada.\\n\\nLa fecha de entrada en vigor que figura al principio de la Política identificará la versión vigente.\\n\\nLos cambios no autorizarán retroactivamente usos de información personal materialmente incompatibles cuando se requiera consentimiento adicional u otra base jurídica."),
    translatedSection('15', 'Contacto', "Preguntas y solicitudes de privacidad:\\n\\n[PRIVACY_CONTACT_EMAIL]\\n\\nSoporte general:\\n\\n[SUPPORT_CONTACT_EMAIL]\\n\\nOperador:\\n\\n[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]\\n\\nEstos datos de identidad de producción deben completarse antes del lanzamiento comercial público.")
  ],
  PRIVACY_SOURCE
);

const esTerms = translatedDocument(
  'terms',
  'es',
  'Condiciones del servicio',
  'Estas Condiciones del servicio regulan tu acceso y uso de natalnode.com y de los servicios, software, funciones, contenidos y herramientas relacionados de NatalNode.',
  '[EFFECTIVE_DATE]',
  [
    'Estas Condiciones del servicio («Condiciones») regulan tu acceso y uso de natalnode.com y de los servicios, software, funciones, contenidos y herramientas relacionados de NatalNode (conjuntamente, el «Servicio»).',
    'El Servicio se opera bajo el nombre NatalNode por:',
    '[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]',
    'Al utilizar el Servicio, aceptas estas Condiciones.',
    'Si no estás de acuerdo, no utilices el Servicio.'
  ],
  [
    translatedSection('1', 'Elegibilidad', "Debes tener al menos 13 años para utilizar NatalNode.\\n\\nSi la legislación aplicable exige que seas mayor para celebrar estas Condiciones o consentir de forma independiente al tratamiento de datos pertinente, se aplicará el requisito de edad superior.\\n\\nSi utilizas NatalNode en nombre de una organización, declaras que tienes autoridad para obligar a esa organización."),
    translatedSection('2', 'Qué proporciona NatalNode', "NatalNode proporciona herramientas astrológicas de creación de cartas, educativas, informativas, analíticas e interpretativas.\\n\\nLas funciones pueden incluir:\\n\\n• herramientas de carta natal;\\n• visualización de cartas;\\n• contenido educativo de astrología;\\n• hechos estructurados de cartas;\\n• herramientas de ubicación y resolución temporal;\\n• cartas guardadas o funciones de Vault;\\n• experiencias Discover y Learn;\\n• funciones de comunidad o profesionales;\\n• otras herramientas relacionadas que se introduzcan con el tiempo.\\n\\nNo todas las funciones estarán necesariamente disponibles en todo momento o en todas las regiones."),
    translatedSection('3', 'Astronomía e interpretación astrológica', "NatalNode distingue entre:\\n\\n• la corrección astronómica y de los cálculos de cartas; y\\n• la interpretación astrológica.\\n\\nNatalNode está diseñado para utilizar canales autorizados de cálculo y datos para los hechos astronómicos y de cartas cuando esos hechos se presenten como autorizados.\\n\\nNatalNode no fabrica intencionadamente hechos autorizados de cartas cuando no están disponibles la información necesaria o una fuente de cálculo autorizada.\\n\\nSin embargo, la astrología es un marco interpretativo. NatalNode no presenta las interpretaciones astrológicas como predicciones científicamente establecidas de la personalidad, conducta, relaciones, salud, acontecimientos futuros o resultados vitales de una persona.\\n\\nLos resultados deben entenderse como material educativo, informativo e interpretativo."),
    translatedSection('4', 'No es asesoramiento profesional', "NatalNode no sustituye el criterio profesional cualificado.\\n\\nEl Servicio no proporciona:\\n\\n• asesoramiento médico;\\n• diagnóstico o tratamiento de salud mental o psicológico;\\n• asesoramiento jurídico;\\n• asesoramiento financiero o de inversión;\\n• asesoramiento fiscal;\\n• servicios de emergencia o crisis.\\n\\nNo retrases, sustituyas ni ignores atención o asesoramiento profesional basándote en una interpretación astrológica.\\n\\nNo utilices NatalNode como única base para decisiones que puedan afectar materialmente a la salud, la seguridad, los derechos legales, las finanzas, el empleo, la vivienda, la educación u otros asuntos de alto impacto."),
    translatedSection('5', 'Información de nacimiento y exactitud de las entradas', "Los resultados de las cartas dependen de la información facilitada y de la configuración de cálculo aplicable.\\n\\nEres responsable de la exactitud de la información que proporcionas, incluyendo:\\n\\n• fecha de nacimiento;\\n• hora de nacimiento;\\n• lugar de nacimiento;\\n• ubicación seleccionada;\\n• otra configuración solicitada.\\n\\nUna pequeña diferencia en la hora de nacimiento, la ubicación, la resolución de la zona horaria, la configuración de cálculo o los datos de origen puede afectar a una carta.\\n\\nSi se desconoce la hora de nacimiento, NatalNode puede restringir u omitir resultados que no puedan establecerse verazmente sin ella, en lugar de sustituirla por una hora inventada.\\n\\nNatalNode no garantiza que la información de nacimiento proporcionada por el usuario sea exacta."),
    translatedSection('6', 'Información sobre otras personas', "Solo puedes utilizar NatalNode con información personal que tengas derecho legal a proporcionar.\\n\\nSi envías la información de nacimiento u otra información personal de otra persona, declaras que tienes una base jurídica adecuada, un motivo legítimo o permiso para hacerlo.\\n\\nNo puedes utilizar NatalNode para recopilar, exponer, acosar, perseguir, perfilar o explotar a otra persona sin justificación legal."),
    translatedSection('7', 'Ubicación y datos de terceros', "NatalNode puede utilizar servicios geográficos o de infraestructura de terceros, incluido GeoNames o proveedores sucesores, para apoyar la resolución de ubicaciones.\\n\\nLos datos de terceros pueden contener errores, omisiones, retrasos o ambigüedades.\\n\\nNatalNode puede exigirte que elijas explícitamente entre varios lugares candidatos en vez de adivinar la ubicación deseada.\\n\\nLos datos geográficos de terceros no establecen por sí solos todos los aspectos de la autoridad temporal histórica ni del cálculo astronómico."),
    translatedSection('8', 'Cuentas', "Algunas funciones pueden requerir una cuenta.\\n\\nEres responsable de:\\n\\n• mantener el control de tu método de autenticación;\\n• proporcionar información exacta de la cuenta;\\n• proteger el acceso a la cuenta;\\n• notificar a NatalNode cualquier acceso no autorizado sospechado;\\n• la actividad realizada mediante tu cuenta, salvo en la medida causada por NatalNode o por circunstancias respecto de las cuales la legislación aplicable atribuya la responsabilidad a otra parte.\\n\\nNo puedes transferir, vender, alquilar ni utilizar indebidamente una cuenta infringiendo estas Condiciones."),
    translatedSection('9', 'Vault y contenido guardado', "Si NatalNode ofrece cartas, notas o funciones de Vault guardadas, controlas si guardas la información que reúna los requisitos.\\n\\nEl almacenamiento no está garantizado como permanente.\\n\\nCuando corresponda, debes conservar copias independientes de la información importante para ti.\\n\\nNatalNode puede establecer límites técnicos, de almacenamiento o de nivel de producto razonables, pero la exactitud científica o de cálculo no se degradará intencionadamente según el nivel de suscripción."),
    translatedSection('10', 'Comunidad y contenido del usuario', "Cuando NatalNode te permita enviar texto, perfiles, preguntas, comentarios, información profesional u otro contenido («Contenido del usuario»), conservas la titularidad de los derechos que ya tengas sobre él.\\n\\nConcedes a NatalNode una licencia no exclusiva, mundial y libre de regalías para alojar, almacenar, reproducir, formatear, mostrar, distribuir y procesar técnicamente el Contenido del usuario únicamente cuando sea razonablemente necesario para:\\n\\n• operar la función en la que lo enviaste;\\n• mostrar el contenido público que pretendías publicar;\\n• moderar y proteger el Servicio;\\n• mantener copias de seguridad;\\n• cumplir la ley;\\n• hacer cumplir estas Condiciones.\\n\\nLa licencia termina cuando se elimina el contenido pertinente, salvo en la medida en que la conservación continuada sea razonablemente necesaria para copias de seguridad, obligaciones legales, registros de seguridad, disputas o contenido que ya se haya compartido legalmente o incorporado a interacciones con otras personas.\\n\\nDeclaras que tienes los derechos necesarios para enviar el Contenido del usuario."),
    translatedSection('11', 'Comentarios', "Si proporcionas voluntariamente sugerencias, ideas, informes de errores o comentarios sobre el producto, NatalNode puede utilizar esos comentarios para desarrollar y mejorar el Servicio sin obligación de compensarte.\\n\\nEsto no transfiere la titularidad de información confidencial no relacionada ni de información personal."),
    translatedSection('12', 'Uso aceptable', "No puedes utilizar NatalNode para:\\n\\n• infringir la legislación aplicable;\\n• infringir la privacidad o los derechos de propiedad intelectual de otra persona;\\n• enviar información que no tengas derecho a proporcionar;\\n• acosar, amenazar, perseguir, explotar o engañar a otra persona;\\n• publicar contenido ilegal, abusivo o malicioso;\\n• suplantar a otra persona u organización;\\n• obtener acceso no autorizado a cuentas, sistemas, redes o datos;\\n• eludir la seguridad, los límites de velocidad, los controles de acceso o las restricciones técnicas;\\n• distribuir malware o código malicioso;\\n• interferir con la disponibilidad o integridad del Servicio;\\n• extraer o recopilar información personal infringiendo la ley aplicable o los controles del producto;\\n• aplicar ingeniería inversa a partes protegidas del Servicio salvo cuando la ley aplicable lo permita expresamente;\\n• utilizar métodos automatizados de forma que carguen o interrumpan materialmente el Servicio;\\n• presentar los resultados de NatalNode como asesoramiento profesional, científico, médico, jurídico o financiero garantizado;\\n• utilizar los resultados de NatalNode para tomar decisiones de alto impacto no autorizadas sobre otra persona.\\n\\nNatalNode puede adoptar medidas proporcionales contra el abuso, incluyendo limitar el acceso, retirar contenido o suspender cuentas."),
    translatedSection('13', 'Propiedad intelectual de NatalNode', "Salvo el Contenido del usuario y los materiales de terceros, NatalNode y sus licenciantes conservan todos los derechos sobre el Servicio, incluidos:\\n\\n• software;\\n• código fuente y objeto;\\n• interfaces;\\n• diseño visual;\\n• marcas comerciales;\\n• identidad de marca;\\n• documentación;\\n• contenido educativo original;\\n• estructuras de datos y recopilaciones en la medida protegida por la ley.\\n\\nSujeto a estas Condiciones, NatalNode te concede un derecho limitado, no exclusivo, intransferible y revocable para utilizar el Servicio con fines personales lícitos o fines organizativos autorizados.\\n\\nNo se te transfiere ningún derecho de propiedad."),
    translatedSection('14', 'Servicios y contenidos de terceros', "NatalNode puede depender de productos, datos, sitios web, plataformas o infraestructura de terceros o enlazarlos.\\n\\nLos servicios de terceros se rigen por sus propias condiciones y políticas cuando corresponda.\\n\\nNatalNode no es responsable de los actos independientes, servicios, disponibilidad, políticas o contenidos de un tercero, salvo cuando la legislación aplicable disponga lo contrario.\\n\\nLa presencia de una integración de terceros no implica la aprobación de cada declaración o servicio ofrecido por ese proveedor."),
    translatedSection('15', 'Servicios gratuitos y de pago', "NatalNode puede ofrecer funciones gratuitas y posteriormente ofrecer productos o suscripciones de pago.\\n\\nLa existencia de estas Condiciones no significa que actualmente haya disponible un plan de pago.\\n\\nSi se ofrecen servicios de pago, el precio, el periodo de facturación, las condiciones de renovación, los derechos de cancelación, los impuestos y las demás condiciones específicas de la transacción se comunicarán antes de la compra según exija la legislación aplicable.\\n\\nNada de un nivel de pago permite a NatalNode proporcionar intencionadamente cálculos astronómicos autorizados menos exactos que los proporcionados a usuarios gratuitos con la misma configuración científica.\\n\\nLos derechos de los consumidores que no puedan renunciarse legalmente no se ven afectados."),
    translatedSection('16', 'Cambios y disponibilidad del Servicio', "NatalNode es un servicio en evolución.\\n\\nPodemos:\\n\\n• añadir, modificar, suspender o retirar funciones;\\n• actualizar contenidos;\\n• cambiar la infraestructura técnica;\\n• sustituir proveedores externos;\\n• mejorar los sistemas de cálculo o presentación;\\n• imponer límites operativos razonables.\\n\\nCuando un cambio afecte materialmente a derechos contractuales de pago, prácticas de datos personales o derechos protegidos por la legislación aplicable, NatalNode proporcionará cualquier aviso o recurso exigido por la ley.\\n\\nNatalNode no promete disponibilidad ininterrumpida ni sin errores."),
    translatedSection('17', 'Funciones experimentales y de desarrollo', "Las funciones identificadas expresamente como:\\n\\n• desarrollo;\\n• vista previa;\\n• beta;\\n• fixture;\\n• experimental;\\n• investigación incompleta;\\n\\nno representan que la función sea autorizada para producción.\\n\\nLos fixtures de desarrollo no deben tratarse como resultados astronómicos personales reales.\\n\\nLa producción comercial pública no debe sustituir silenciosamente datos de fixtures por datos autorizados no disponibles."),
    translatedSection('18', 'Suspensión y terminación', "Puedes dejar de utilizar el Servicio en cualquier momento.\\n\\nCuando esté disponible la eliminación de cuentas, puedes solicitarla o realizarla conforme a la Política de privacidad y a los requisitos legales de conservación.\\n\\nNatalNode puede suspender o terminar el acceso cuando sea razonablemente necesario debido a:\\n\\n• incumplimiento material de estas Condiciones;\\n• actividad ilegal;\\n• fraude o abuso;\\n• amenazas de seguridad;\\n• riesgo para otros usuarios o la infraestructura;\\n• falta de pago de un servicio de pago aplicable;\\n• requisitos legales.\\n\\nCuando sea adecuado y razonablemente posible, NatalNode puede avisar o dar la oportunidad de remediar el incumplimiento."),
    translatedSection('19', 'Exenciones de responsabilidad', "En la máxima medida permitida por la legislación aplicable, el Servicio se proporciona «según disponibilidad».\\n\\nNatalNode no garantiza que:\\n\\n• el Servicio siempre esté ininterrumpido;\\n• todas las fuentes de datos de terceros estén siempre disponibles;\\n• toda la información introducida por los usuarios sea exacta;\\n• una interpretación astrológica prediga o explique un resultado individual;\\n• el uso del Servicio produzca un resultado personal, profesional, financiero, sanitario, relacional o de otro tipo concreto.\\n\\nNada de estas Condiciones excluye garantías o derechos de los consumidores que legalmente no puedan excluirse."),
    translatedSection('20', 'Limitación de responsabilidad', "En la máxima medida permitida por la legislación aplicable, NatalNode y el operador correspondiente no serán responsables de daños indirectos, incidentales, especiales, consecuentes, ejemplares o punitivos derivados del uso del Servicio cuando dicha exclusión esté permitida legalmente.\\n\\nNatalNode no es responsable de las decisiones que tomes únicamente basándote en una interpretación astrológica.\\n\\nPara las reclamaciones cuya responsabilidad pueda limitarse legalmente, la responsabilidad agregada derivada del Servicio no excederá de la mayor de las siguientes cantidades:\\n\\n• la cantidad que hayas pagado directamente a NatalNode por el Servicio durante los 12 meses anteriores al hecho que origine la reclamación; o\\n• 100 USD.\\n\\nEsta limitación no se aplica cuando la responsabilidad no pueda excluirse o limitarse legalmente, incluidas las protecciones obligatorias de los consumidores u otros derechos irrenunciables.\\n\\nEl límite monetario final queda sujeto a revisión cuando se establezcan la entidad operativa estadounidense y la jurisdicción aplicable."),
    translatedSection('21', 'Indemnización', "En la medida permitida por la legislación aplicable, aceptas indemnizar y mantener indemne al operador de NatalNode frente a reclamaciones de terceros derivadas de:\\n\\n• el Contenido del usuario que envíes ilegalmente;\\n• tu incumplimiento material de estas Condiciones;\\n• tu uso ilegal de la información de otra persona;\\n• la infracción de los derechos de otra persona.\\n\\nEsta disposición no te obliga a indemnizar a NatalNode por conductas de las que la legislación aplicable haga responsable a NatalNode."),
    translatedSection('22', 'Privacidad', "La recopilación y el uso de información personal por NatalNode se describen en la Política de privacidad de NatalNode.\\n\\nLa Política de privacidad es una parte importante de tu comprensión del Servicio, pero no pretende renunciar a los derechos que te concede la legislación de privacidad aplicable."),
    translatedSection('23', 'Cambios en estas Condiciones', "NatalNode puede actualizar estas Condiciones cuando cambien el Servicio o la legislación aplicable.\\n\\nLos cambios materiales se comunicarán de una manera adecuada.\\n\\nSi la legislación aplicable exige una aceptación afirmativa de un cambio, el cambio no te vinculará simplemente porque una página se haya actualizado silenciosamente.\\n\\nLa fecha de entrada en vigor identifica la versión vigente."),
    translatedSection('24', 'Legislación aplicable y disputas', "[GOVERNING_LAW_AND_FORUM_CLAUSE]\\n\\nEsta disposición se aplaza intencionadamente hasta que se establezcan la entidad operativa y la jurisdicción de producción.\\n\\nAntes del lanzamiento comercial público, debe sustituirse por una cláusula final revisada con respecto a:\\n\\n• el estado en el que se constituya la entidad operativa estadounidense;\\n• el vínculo empresarial real del operador;\\n• las leyes de protección de los consumidores aplicables a los mercados objetivo;\\n• cualquier decisión de arbitraje o foro judicial adoptada por el Product Owner.\\n\\nHasta entonces, no se declara ninguna jurisdicción ficticia.\\n\\nLos derechos obligatorios de los consumidores conforme a la legislación aplicable no pueden renunciarse mediante este marcador."),
    translatedSection('25', 'Contacto', "Soporte general:\\n\\n[SUPPORT_CONTACT_EMAIL]\\n\\nAvisos legales:\\n\\n[LEGAL_CONTACT_EMAIL]\\n\\nOperador:\\n\\n[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]\\n\\nEstos campos deben completarse antes del lanzamiento comercial público.")
  ],
  TERMS_SOURCE
);

const frPrivacy = translatedDocument(
  'privacy',
  'fr',
  'Politique de confidentialité',
  'Cette Politique de confidentialité explique quelles informations personnelles NatalNode collecte, pourquoi elles sont traitées, comment elles sont utilisées et communiquées, combien de temps elles peuvent être conservées, ainsi que les choix et droits dont vous disposez.',
  '[EFFECTIVE_DATE]',
  [
    'NatalNode fournit des outils de création de cartes astrologiques, éducatifs, informatifs et interprétatifs sur natalnode.com et par l’intermédiaire de services associés (le « Service »).',
    'Cette Politique de confidentialité explique quelles informations personnelles NatalNode collecte, pourquoi elles sont traitées, comment elles sont utilisées et communiquées, combien de temps elles peuvent être conservées, ainsi que les choix et droits dont vous disposez.',
    'Aux fins de la législation applicable en matière de protection des données, l’opérateur identifié ci-dessous est le responsable du traitement ou l’entreprise responsable des informations personnelles traitées par le Service.',
    'Opérateur : [OPERATOR_LEGAL_NAME]\\nAdresse enregistrée : [OPERATOR_ADDRESS]\\nContact confidentialité : [PRIVACY_CONTACT_EMAIL]',
    'Les informations relatives à l’opérateur doivent être complétées avant le lancement commercial public.'
  ],
  [
    translatedSection('1', 'Informations que nous recueillons', "1.1 Informations de compte\\n\\nSi vous créez ou utilisez un compte, nous pouvons traiter notamment :\\n\\n• l’adresse e-mail ;\\n• les identifiants d’authentification ;\\n• le statut du compte ;\\n• les enregistrements d’authentification et de sécurité ;\\n• les préférences et paramètres du compte.\\n\\nLorsqu’une connexion par un tiers est proposée, nous recevons uniquement les informations nécessaires pour authentifier ou exploiter le compte, dans la mesure permise par ce fournisseur et vos paramètres.\\n\\n1.2 Informations de naissance et de carte\\n\\nPour fournir les fonctions relatives aux cartes, vous pouvez communiquer notamment :\\n\\n• la date de naissance ;\\n• l’heure de naissance, lorsqu’elle est connue ;\\n• le lieu de naissance ou la recherche de lieu ;\\n• le lieu de naissance canonique sélectionné ;\\n• les coordonnées géographiques dérivées du lieu sélectionné ;\\n• l’identité de fuseau horaire IANA ;\\n• les informations de résolution temporelle nécessaires pour établir l’instant pertinent ;\\n• les choix de configuration de la carte ;\\n• les données de carte résultantes et les interprétations associées.\\n\\nNatalNode traite les informations de naissance et de carte comme des informations de produit sensibles du point de vue de la confidentialité, même lorsqu’une loi donnée ne classe pas chaque composant comme une information personnelle légalement sensible.\\n\\nSi l’heure de naissance est inconnue, NatalNode peut conserver cet état comme inconnu au lieu d’inventer une heure de remplacement.\\n\\n1.3 Cartes enregistrées et informations du Vault\\n\\nSi vous choisissez d’enregistrer des cartes ou du contenu associé dans un Vault ou une fonction de compte similaire, nous pouvons conserver :\\n\\n• les entrées de carte ;\\n• les résultats de carte ;\\n• les libellés ou noms que vous attribuez ;\\n• les notes ou paramètres associés ;\\n• les horodatages et relations de compte nécessaires au fonctionnement de la fonction d’enregistrement.\\n\\nL’enregistrement d’informations est distinct de la simple saisie d’informations pour un calcul lorsque l’architecture du produit permet un usage temporaire.\\n\\n1.4 Informations concernant d’autres personnes\\n\\nLe Service peut vous permettre de saisir des informations relatives à une autre personne, par exemple pour créer ou comparer des cartes.\\n\\nVous devez vous assurer de disposer d’une base légale appropriée ou d’une autorisation pour fournir les informations personnelles d’une autre personne à NatalNode.\\n\\nVous ne devez pas soumettre les informations d’une autre personne sans raison légitime ni autorité appropriée.\\n\\n1.5 Contributions de la communauté, de praticiens, commentaires et autres\\n\\nLorsque ces fonctions sont disponibles, nous pouvons traiter les informations que vous soumettez volontairement par l’intermédiaire de :\\n\\n• questions ou discussions de la communauté ;\\n• profils ou candidatures de praticiens ;\\n• processus de modération ;\\n• formulaires de commentaires ;\\n• communications avec le support ;\\n• signalements ou autres contributions générées par les utilisateurs.\\n\\nLes contributions publiques peuvent être visibles par d’autres utilisateurs comme l’indique la fonction concernée.\\n\\n1.6 Informations techniques et de sécurité\\n\\nLorsque vous utilisez le Service, les serveurs et systèmes de sécurité peuvent traiter automatiquement notamment :\\n\\n• l’adresse IP ;\\n• les horodatages des requêtes ;\\n• les informations du navigateur et de l’appareil ;\\n• les informations du système d’exploitation ;\\n• les routes demandées ;\\n• les événements de session et d’authentification ;\\n• les événements de sécurité ;\\n• les informations de diagnostic et d’erreur ;\\n• des informations approximatives de réseau ou de région lorsque cela est nécessaire à la sécurité ou à la fourniture du Service.\\n\\nNatalNode n’exige pas la géolocalisation précise de l’appareil simplement pour déduire votre lieu de naissance. L’autorité du lieu de naissance est établie par la saisie explicite du lieu et la sélection d’un candidat.\\n\\n1.7 Cookies et technologies similaires\\n\\nNatalNode peut utiliser des cookies ou des technologies locales équivalentes nécessaires pour :\\n\\n• maintenir les sessions d’authentification ;\\n• préserver la sécurité ;\\n• prévenir les abus ;\\n• mémoriser les préférences essentielles ;\\n• fournir les fonctions essentielles du Service.\\n\\nLes technologies non essentielles d’analyse, de publicité ou de suivi intersites ne seront pas introduites sans les informations et contrôles requis par la législation applicable."),
    translatedSection('2', 'Comment nous utilisons les informations personnelles', "Nous pouvons traiter les informations personnelles afin de :\\n\\n• fournir les fonctions de création de cartes et du Service demandées ;\\n• résoudre les lieux saisis par les utilisateurs en lieux canoniques ;\\n• établir les informations temporelles nécessaires aux calculs de cartes demandés ;\\n• créer et gérer les comptes ;\\n• exploiter les fonctions de cartes enregistrées et de Vault ;\\n• fournir des fonctions communautaires, de praticiens, de commentaires ou de support ;\\n• authentifier les utilisateurs et maintenir les sessions ;\\n• sécuriser le Service et détecter les fraudes, abus, attaques ou défaillances techniques ;\\n• diagnostiquer et améliorer la fiabilité, l’accessibilité et les performances ;\\n• communiquer avec vous au sujet de votre compte ou du Service ;\\n• respecter les obligations légales et faire appliquer nos Conditions ;\\n• protéger les droits, la sécurité et l’intégrité des utilisateurs, de NatalNode et d’autrui.\\n\\nNatalNode n’utilise pas les informations personnelles de naissance pour fabriquer des faits astronomiques lorsque les entrées de calcul ou services autorisés ne sont pas disponibles."),
    translatedSection('3', 'Bases légales du traitement', "Lorsque des lois telles que le RGPD exigent une base légale, NatalNode s’appuie selon le cas sur :\\n\\nL’exécution d’un contrat ou les mesures demandées par vous : par exemple fournir un compte, générer une carte demandée, résoudre un lieu demandé ou conserver le contenu que vous choisissez d’enregistrer.\\n\\nLes intérêts légitimes : par exemple exploiter et sécuriser le Service, détecter les abus, corriger les défaillances, maintenir la sécurité des réseaux et des informations et améliorer la fiabilité lorsque ces intérêts ne sont pas supplantés par vos droits.\\n\\nLe consentement : lorsque la loi l’exige, notamment pour les communications facultatives ou technologies non essentielles.\\n\\nLes obligations légales : lorsque le traitement est nécessaire pour respecter la loi applicable, une procédure légale valide, des exigences comptables ou des obligations réglementaires."),
    translatedSection('4', 'Résolution des lieux et GeoNames', "NatalNode peut utiliser GeoNames ou un autre fournisseur approuvé d’informations de lieu pour aider à convertir les recherches de lieux en candidats structurés.\\n\\nLes informations de résolution de lieu peuvent inclure :\\n\\n• la recherche de lieu que vous envoyez ;\\n• le nom canonique du lieu ;\\n• les informations de pays et de région administrative ;\\n• la latitude et la longitude ;\\n• l’identité du fuseau horaire ;\\n• les identifiants d’enregistrement du fournisseur.\\n\\nNatalNode exige une sélection explicite lorsque plusieurs lieux plausibles existent et ne considère pas le texte brut de l’utilisateur comme l’identité de lieu faisant autorité.\\n\\nLes données et services web de GeoNames sont fournis sous une licence d’attribution et GeoNames décrit ses données comme fournies « en l’état ». NatalNode maintient donc l’attribution du fournisseur lorsque cela est applicable.\\n\\nUn fournisseur de lieux établit l’identité du lieu et les métadonnées géographiques associées. Il n’établit pas à lui seul les décalages historiques autorisés de l’heure de naissance ni les faits astronomiques d’une carte."),
    translatedSection('5', 'Fournisseurs d’astronomie et services techniques', "NatalNode peut utiliser des fournisseurs tiers autorisés d’infrastructure, de données, de communications, d’hébergement, de bases de données, de sécurité, de courrier électronique et de services liés à l’astronomie lorsque cela est nécessaire pour exploiter le Service.\\n\\nNatalNode cherche à limiter les données communiquées aux fournisseurs de services aux informations raisonnablement nécessaires à leur fonction.\\n\\nLe fournisseur d’astronomie de production sera autorisé commercialement avant le lancement des fonctions de production concernées.\\n\\nUne liste actuelle des services tiers importants ou sous-traitants peut être tenue séparément et mise à jour lorsque les fournisseurs changent.\\n\\nLe changement d’un fournisseur d’infrastructure ou d’astronomie n’autorise pas NatalNode à utiliser vos informations pour une finalité sans rapport."),
    translatedSection('6', 'Comment nous communiquons les informations personnelles', "NatalNode peut communiquer les informations personnelles aux catégories de destinataires suivantes lorsque cela est nécessaire :\\n\\nFournisseurs de services\\n\\nEntreprises fournissant des services d’infrastructure ou d’exploitation tels que :\\n\\n• l’hébergement ;\\n• les bases de données ;\\n• l’authentification ;\\n• l’envoi de courriers électroniques ;\\n• la sécurité ;\\n• le diagnostic ;\\n• la résolution de lieux ;\\n• l’infrastructure autorisée de données astronomiques ;\\n• le traitement des paiements si des produits payants sont proposés.\\n\\nElles ne reçoivent les informations que pour la finalité opérationnelle pertinente et sont soumises aux obligations contractuelles ou légales applicables.\\n\\nAutres utilisateurs\\n\\nLes informations ne sont communiquées à d’autres utilisateurs que lorsque vous utilisez intentionnellement une fonction publique ou collaborative, comme du contenu communautaire public ou un profil public de praticien.\\n\\nLes informations privées du Vault ne deviennent pas publiques du seul fait de leur enregistrement.\\n\\nCommunications légales et de sécurité\\n\\nLes informations peuvent être communiquées lorsqu’il est raisonnablement nécessaire de :\\n\\n• respecter la loi applicable ou une procédure légale valide ;\\n• répondre à des demandes gouvernementales licites ;\\n• enquêter sur une fraude ou un abus ;\\n• protéger la sécurité du Service ;\\n• protéger des droits légaux ou la sécurité.\\n\\nTransferts d’entreprise\\n\\nSi NatalNode, ou la quasi-totalité des actifs concernés, est réorganisé, financé, acquis, fusionné, transféré ou vendu, les informations personnelles peuvent être transférées dans le cadre de cette opération, sous réserve de la loi applicable et de protections appropriées.\\n\\nSi le Service passe d’une structure de développement individuelle détenue par le fondateur à une entité opérationnelle ultérieure, les avis et informations de responsable requis seront mis à jour avant cette transition ou au moment où la loi l’exige."),
    translatedSection('7', 'Vente et utilisation publicitaire des informations personnelles', "NatalNode ne vend pas les informations personnelles contre de l’argent.\\n\\nNatalNode n’utilise pas les informations de naissance ou de carte pour la publicité comportementale intercontextuelle de tiers.\\n\\nSi NatalNode introduit ultérieurement une publicité ou des pratiques de données constituant une « vente », un « partage » ou de la publicité ciblée au sens de la législation applicable, ces pratiques ne commenceront pas avant la mise à jour de l’avis applicable et la mise à disposition des contrôles de consentement ou d’opposition requis."),
    translatedSection('8', 'Conservation des données', "NatalNode conserve les informations personnelles uniquement pendant la durée raisonnablement nécessaire à la finalité de leur collecte, notamment pour :\\n\\n• exploiter un compte actif ;\\n• conserver les informations que vous avez choisi d’enregistrer ;\\n• fournir les services demandés ;\\n• conserver les enregistrements de sécurité et de prévention des abus ;\\n• résoudre les litiges ;\\n• faire appliquer les accords ;\\n• respecter les obligations légales, comptables ou réglementaires.\\n\\nLorsqu’un compte ou un élément enregistré est supprimé, les informations associées sont supprimées ou désidentifiées selon le processus applicable, sous réserve des besoins légitimes de conservation liés aux sauvegardes, à la sécurité, à la prévention des fraudes, à la loi ou à la conformité.\\n\\nLes sauvegardes peuvent conserver des informations pendant une durée limitée jusqu’à la fin de la rotation normale des sauvegardes.\\n\\nNatalNode tiendra un calendrier interne de conservation adapté à l’architecture de production plutôt que de conserver indéfiniment des informations sans finalité."),
    translatedSection('9', 'Transferts internationaux de données', "NatalNode est conçu comme un service international et son infrastructure ou ses fournisseurs peuvent exercer dans des pays différents de celui où vous vivez.\\n\\nLorsque la loi applicable exige des garanties pour les transferts internationaux, NatalNode utilisera des mécanismes légalement reconnus adaptés au transfert, tels que :\\n\\n• des décisions d’adéquation ;\\n• des garanties contractuelles ;\\n• des clauses contractuelles types approuvées ;\\n• d’autres mécanismes légaux de transfert.\\n\\nLes régions d’hébergement de production précises et les sous-traitants concernés doivent être examinés avant le lancement."),
    translatedSection('10', 'Vos droits en matière de confidentialité', "Selon votre lieu de résidence et la loi applicable, vous pouvez disposer du droit de :\\n\\n• demander l’accès aux informations personnelles ;\\n• obtenir des informations sur leur traitement ;\\n• corriger les informations inexactes ;\\n• demander leur suppression ;\\n• limiter certains traitements ;\\n• vous opposer à certains traitements ;\\n• recevoir certaines informations dans un format portable ;\\n• retirer votre consentement lorsque le traitement repose sur celui-ci ;\\n• vous opposer à certaines pratiques de vente, de partage ou de publicité ciblée lorsque cela est applicable ;\\n• faire appel de certaines décisions relatives à la confidentialité lorsque cela est applicable ;\\n• déposer une réclamation auprès d’une autorité de protection des données compétente.\\n\\nPour exercer un droit applicable, contactez :\\n\\n[PRIVACY_CONTACT_EMAIL]\\n\\nNatalNode peut devoir vérifier votre identité avant de traiter certaines demandes et n’utilisera les informations de vérification que de manière appropriée pour cette procédure.\\n\\nNous ne vous discriminerons pas illégalement parce que vous exercez vos droits applicables."),
    translatedSection('11', 'Sécurité', "NatalNode mettra en œuvre des mesures techniques et organisationnelles raisonnables destinées à protéger les informations personnelles contre :\\n\\n• l’accès non autorisé ;\\n• la divulgation non autorisée ;\\n• la modification ;\\n• la perte accidentelle ;\\n• la destruction ;\\n• l’utilisation abusive.\\n\\nLes mesures de sécurité seront proportionnées à la nature des informations et à l’architecture de production.\\n\\nAucun système, mécanisme de stockage, transmission réseau ou service en ligne ne peut être garanti comme absolument sûr."),
    translatedSection('12', 'Enfants', "NatalNode ne s’adresse pas aux enfants de moins de 13 ans.\\n\\nVous devez avoir au moins 13 ans pour utiliser le Service.\\n\\nLorsque la loi applicable impose un âge plus élevé pour qu’une personne puisse consentir seule au traitement des informations personnelles ou à l’utilisation d’un service en ligne, cet âge minimum supérieur s’applique.\\n\\nNatalNode ne cherche pas sciemment à recueillir des informations personnelles auprès d’enfants de moins de 13 ans. Si nous apprenons que de telles informations ont été collectées contrairement aux exigences applicables, nous prendrons les mesures appropriées pour les supprimer ou les traiter autrement."),
    translatedSection('13', 'Résultats automatisés et interprétatifs', "NatalNode peut générer ou présenter des interprétations astrologiques fondées sur des informations structurées de carte.\\n\\nCette interprétation ne signifie pas que NatalNode prend des décisions juridiquement importantes à votre sujet.\\n\\nNatalNode n’utilise pas l’interprétation astrologique pour déterminer l’admissibilité à l’emploi, au crédit, au logement, à l’assurance, aux soins de santé, à l’éducation ou à des décisions similaires à fort impact.\\n\\nSi un processus décisionnel automatisé matériellement différent est introduit à l’avenir, cette Politique sera mise à jour comme requis avant le début de cette utilisation."),
    translatedSection('14', 'Modifications de cette Politique de confidentialité', "NatalNode peut mettre à jour cette Politique lorsque le Service, la loi, l’infrastructure ou les pratiques de données changent.\\n\\nLes modifications importantes seront communiquées de manière appropriée.\\n\\nLa date d’entrée en vigueur figurant en tête de la Politique identifiera la version actuelle.\\n\\nLes modifications n’autoriseront pas rétroactivement des utilisations des informations personnelles matériellement incompatibles lorsqu’un consentement supplémentaire ou une autre base légale est requis."),
    translatedSection('15', 'Contact', "Questions et demandes relatives à la confidentialité :\\n\\n[PRIVACY_CONTACT_EMAIL]\\n\\nSupport général :\\n\\n[SUPPORT_CONTACT_EMAIL]\\n\\nOpérateur :\\n\\n[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]\\n\\nCes informations d’identité de production doivent être finalisées avant le lancement commercial public.")
  ],
  PRIVACY_SOURCE
);

const frTerms = translatedDocument(
  'terms',
  'fr',
  'Conditions d’utilisation',
  'Ces Conditions d’utilisation régissent votre accès à natalnode.com et aux services, logiciels, fonctions, contenus et outils associés de NatalNode, ainsi que leur utilisation.',
  '[EFFECTIVE_DATE]',
  [
    'Ces Conditions d’utilisation (« Conditions ») régissent votre accès à natalnode.com et aux services, logiciels, fonctions, contenus et outils associés de NatalNode, ainsi que leur utilisation (collectivement, le « Service »).',
    'Le Service est exploité sous le nom NatalNode par :',
    '[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]',
    'En utilisant le Service, vous acceptez ces Conditions.',
    'Si vous ne les acceptez pas, n’utilisez pas le Service.'
  ],
  [
    translatedSection('1', 'Éligibilité', "Vous devez avoir au moins 13 ans pour utiliser NatalNode.\\n\\nSi la loi applicable exige un âge supérieur pour conclure ces Conditions ou consentir seul au traitement de données concerné, l’âge supérieur s’applique.\\n\\nSi vous utilisez NatalNode pour le compte d’une organisation, vous déclarez avoir le pouvoir d’engager cette organisation."),
    translatedSection('2', 'Ce que fournit NatalNode', "NatalNode fournit des outils de création de cartes astrologiques, éducatifs, informatifs, analytiques et interprétatifs.\\n\\nLes fonctions peuvent inclure :\\n\\n• des outils de carte natale ;\\n• la visualisation de cartes ;\\n• du contenu éducatif sur l’astrologie ;\\n• des faits structurés de carte ;\\n• des outils de lieu et de résolution temporelle ;\\n• des cartes enregistrées ou des fonctions de Vault ;\\n• des expériences Discover et Learn ;\\n• des fonctions communautaires ou de praticiens ;\\n• d’autres outils associés introduits au fil du temps.\\n\\nToutes les fonctions ne sont pas nécessairement disponibles à tout moment ni dans toutes les régions."),
    translatedSection('3', 'Astronomie et interprétation astrologique', "NatalNode distingue :\\n\\n• l’exactitude astronomique et celle des calculs de cartes ; et\\n• l’interprétation astrologique.\\n\\nNatalNode est conçu pour utiliser des chaînes de calcul et de données faisant autorité pour les faits astronomiques et de carte lorsque ces faits sont présentés comme faisant autorité.\\n\\nNatalNode ne fabrique pas intentionnellement de faits de carte faisant autorité lorsque les informations nécessaires ou une source de calcul autorisée ne sont pas disponibles.\\n\\nCependant, l’astrologie est un cadre interprétatif. NatalNode ne présente pas les interprétations astrologiques comme des prédictions scientifiquement établies de la personnalité, du comportement, des relations, de la santé, d’événements futurs ou de résultats de vie.\\n\\nLes résultats doivent être compris comme un contenu éducatif, informatif et interprétatif."),
    translatedSection('4', 'Absence de conseil professionnel', "NatalNode ne remplace pas le jugement d’un professionnel qualifié.\\n\\nLe Service ne fournit pas :\\n\\n• de conseil médical ;\\n• de diagnostic ou traitement de santé mentale ou psychologique ;\\n• de conseil juridique ;\\n• de conseil financier ou d’investissement ;\\n• de conseil fiscal ;\\n• de services d’urgence ou de crise.\\n\\nNe retardez pas, ne remplacez pas et ne négligez pas des soins ou conseils professionnels en vous fondant sur une interprétation astrologique.\\n\\nN’utilisez pas NatalNode comme unique fondement de décisions pouvant avoir un effet important sur la santé, la sécurité, les droits juridiques, les finances, l’emploi, le logement, l’éducation ou d’autres questions à fort impact."),
    translatedSection('5', 'Informations de naissance et exactitude des saisies', "Les résultats d’une carte dépendent des informations fournies et de la configuration de calcul applicable.\\n\\nVous êtes responsable de l’exactitude des informations que vous fournissez, notamment :\\n\\n• la date de naissance ;\\n• l’heure de naissance ;\\n• le lieu de naissance ;\\n• le lieu sélectionné ;\\n• les autres paramètres demandés.\\n\\nUne petite différence d’heure de naissance, de lieu, de résolution de fuseau horaire, de configuration de calcul ou de données sources peut modifier une carte.\\n\\nSi l’heure de naissance est inconnue, NatalNode peut restreindre ou omettre les résultats qui ne peuvent pas être établis fidèlement sans elle plutôt que de la remplacer par une heure inventée.\\n\\nNatalNode ne garantit pas l’exactitude des informations de naissance fournies par l’utilisateur."),
    translatedSection('6', 'Informations concernant d’autres personnes', "Vous ne pouvez utiliser NatalNode qu’avec des informations personnelles que vous êtes légalement autorisé à fournir.\\n\\nSi vous soumettez les informations de naissance ou d’autres informations personnelles d’une autre personne, vous déclarez disposer d’une base légale appropriée, d’une raison légitime ou d’une autorisation.\\n\\nVous ne pouvez pas utiliser NatalNode pour recueillir, exposer, harceler, suivre, profiler ou exploiter une autre personne sans justification légale."),
    translatedSection('7', 'Lieux et données de tiers', "NatalNode peut utiliser des services géographiques ou d’infrastructure tiers, notamment GeoNames ou des fournisseurs qui lui succèdent, pour permettre la résolution des lieux.\\n\\nLes données de tiers peuvent contenir des erreurs, omissions, retards ou ambiguïtés.\\n\\nNatalNode peut vous demander de choisir explicitement entre plusieurs lieux candidats plutôt que de deviner le lieu souhaité.\\n\\nLes données géographiques de tiers n’établissent pas à elles seules tous les aspects de l’autorité temporelle historique ou du calcul astronomique."),
    translatedSection('8', 'Comptes', "Certaines fonctions peuvent nécessiter un compte.\\n\\nVous êtes responsable de :\\n\\n• conserver le contrôle de votre méthode d’authentification ;\\n• fournir des informations de compte exactes ;\\n• protéger l’accès au compte ;\\n• signaler à NatalNode tout accès non autorisé soupçonné ;\\n• l’activité effectuée par votre compte, sauf dans la mesure où elle est causée par NatalNode ou par des circonstances dont la loi applicable attribue la responsabilité ailleurs.\\n\\nVous ne pouvez pas transférer, vendre, louer ou utiliser abusivement un compte en violation de ces Conditions."),
    translatedSection('9', 'Vault et contenu enregistré', "Si NatalNode propose des cartes, notes ou fonctions Vault enregistrées, vous décidez d’enregistrer ou non les informations admissibles.\\n\\nLa conservation n’est pas garantie comme permanente.\\n\\nVous devriez conserver des copies indépendantes des informations importantes pour vous lorsque cela est approprié.\\n\\nNatalNode peut imposer des limites techniques, de stockage ou de niveau de produit raisonnables, mais l’exactitude scientifique ou des calculs ne sera pas volontairement diminuée selon le niveau d’abonnement."),
    translatedSection('10', 'Communauté et contenu utilisateur', "Lorsque NatalNode vous permet de soumettre du texte, des profils, des questions, des commentaires, des informations de praticien ou d’autres contenus (« Contenu utilisateur »), vous conservez les droits que vous détenez déjà sur ce contenu.\\n\\nVous accordez à NatalNode une licence non exclusive, mondiale et libre de redevances pour héberger, stocker, reproduire, formater, afficher, distribuer et traiter techniquement le Contenu utilisateur uniquement dans la mesure raisonnablement nécessaire pour :\\n\\n• exploiter la fonction dans laquelle vous l’avez soumis ;\\n• afficher le contenu public que vous souhaitiez publier ;\\n• modérer et sécuriser le Service ;\\n• maintenir des sauvegardes ;\\n• respecter la loi ;\\n• faire appliquer ces Conditions.\\n\\nCette licence prend fin lorsque le contenu concerné est supprimé, sauf dans la mesure où sa conservation continue est raisonnablement nécessaire pour les sauvegardes, obligations légales, enregistrements de sécurité, litiges ou contenu déjà partagé légalement ou incorporé à des interactions avec d’autres personnes.\\n\\nVous déclarez disposer des droits nécessaires pour soumettre le Contenu utilisateur."),
    translatedSection('11', 'Commentaires', "Si vous fournissez volontairement des suggestions, idées, rapports de bogues ou commentaires sur le produit, NatalNode peut les utiliser pour développer et améliorer le Service sans obligation de vous indemniser.\\n\\nCela ne transfère pas la propriété d’informations confidentielles sans rapport ni d’informations personnelles."),
    translatedSection('12', 'Utilisation acceptable', "Vous ne pouvez pas utiliser NatalNode pour :\\n\\n• violer la loi applicable ;\\n• violer la vie privée ou les droits de propriété intellectuelle d’autrui ;\\n• soumettre des informations que vous n’êtes pas autorisé à fournir ;\\n• harceler, menacer, suivre, exploiter ou tromper autrui ;\\n• publier du contenu illégal, abusif ou malveillant ;\\n• usurper l’identité d’une personne ou organisation ;\\n• obtenir un accès non autorisé à des comptes, systèmes, réseaux ou données ;\\n• contourner la sécurité, les limites de débit, les contrôles d’accès ou les restrictions techniques ;\\n• distribuer des logiciels malveillants ou du code malveillant ;\\n• nuire à la disponibilité ou à l’intégrité du Service ;\\n• extraire ou collecter des informations personnelles en violation de la loi ou des contrôles du produit ;\\n• faire de l’ingénierie inverse sur les parties protégées du Service sauf autorisation expresse de la loi ;\\n• utiliser des méthodes automatisées de façon à charger ou perturber matériellement le Service ;\\n• présenter les résultats de NatalNode comme un conseil professionnel, scientifique, médical, juridique ou financier garanti ;\\n• utiliser les résultats de NatalNode pour prendre des décisions non autorisées à fort impact concernant une autre personne.\\n\\nNatalNode peut prendre des mesures proportionnées contre les abus, notamment limiter l’accès, retirer du contenu ou suspendre des comptes."),
    translatedSection('13', 'Propriété intellectuelle de NatalNode', "À l’exception du Contenu utilisateur et des éléments de tiers, NatalNode et ses concédants conservent tous les droits sur le Service, notamment :\\n\\n• les logiciels ;\\n• le code source et objet ;\\n• les interfaces ;\\n• la conception visuelle ;\\n• les marques ;\\n• l’identité de marque ;\\n• la documentation ;\\n• le contenu éducatif original ;\\n• les structures et compilations de données dans la mesure protégée par la loi.\\n\\nSous réserve de ces Conditions, NatalNode vous accorde un droit limité, non exclusif, non transférable et révocable d’utiliser le Service à des fins personnelles licites ou organisationnelles autorisées.\\n\\nAucun droit de propriété ne vous est transféré."),
    translatedSection('14', 'Services et contenus de tiers', "NatalNode peut dépendre de produits, données, sites, plateformes ou infrastructures de tiers, ou y renvoyer.\\n\\nLes services tiers sont régis par leurs propres conditions et politiques lorsqu’elles s’appliquent.\\n\\nNatalNode n’est pas responsable des actes indépendants, services, disponibilité, politiques ou contenus d’un tiers, sauf disposition contraire de la loi applicable.\\n\\nLa présence d’une intégration tierce n’implique pas l’approbation de chaque déclaration ou service offert par ce fournisseur."),
    translatedSection('15', 'Services gratuits et payants', "NatalNode peut proposer des fonctions gratuites et proposer ultérieurement des produits ou abonnements payants.\\n\\nL’existence de ces Conditions ne signifie pas qu’une offre payante est actuellement disponible.\\n\\nSi des services payants sont proposés, le prix, la période de facturation, les conditions de renouvellement, les droits d’annulation, les taxes et les autres conditions propres à la transaction seront communiqués avant l’achat comme l’exige la loi applicable.\\n\\nAucune offre payante ne permet à NatalNode de fournir intentionnellement des calculs astronomiques faisant autorité moins exacts que ceux fournis aux utilisateurs gratuits avec la même configuration scientifique.\\n\\nLes droits des consommateurs auxquels il ne peut légalement être renoncé restent inchangés."),
    translatedSection('16', 'Modifications et disponibilité du Service', "NatalNode est un service en évolution.\\n\\nNous pouvons :\\n\\n• ajouter, modifier, suspendre ou supprimer des fonctions ;\\n• mettre à jour le contenu ;\\n• modifier l’infrastructure technique ;\\n• remplacer des fournisseurs tiers ;\\n• améliorer les systèmes de calcul ou de présentation ;\\n• imposer des limites opérationnelles raisonnables.\\n\\nLorsqu’une modification affecte matériellement des droits contractuels payants, des pratiques relatives aux données personnelles ou des droits protégés par la loi, NatalNode fournira tout avis ou recours exigé par la loi.\\n\\nNatalNode ne promet pas une disponibilité ininterrompue ou exempte d’erreurs."),
    translatedSection('17', 'Fonctions expérimentales et de développement', "Les fonctions explicitement désignées comme :\\n\\n• développement ;\\n• aperçu ;\\n• bêta ;\\n• fixture ;\\n• expérimentales ;\\n• recherche incomplète ;\\n\\nne constituent pas des déclarations selon lesquelles la fonction fait autorité en production.\\n\\nLes fixtures de développement ne doivent pas être traitées comme de vrais résultats astronomiques personnels.\\n\\nLa production commerciale publique ne doit pas remplacer silencieusement des données faisant autorité par des données de fixture lorsqu’elles sont indisponibles."),
    translatedSection('18', 'Suspension et résiliation', "Vous pouvez cesser d’utiliser le Service à tout moment.\\n\\nLorsque la suppression d’un compte est disponible, vous pouvez la demander ou l’effectuer conformément à la Politique de confidentialité et aux obligations légales de conservation.\\n\\nNatalNode peut suspendre ou résilier l’accès lorsqu’il est raisonnablement nécessaire en raison de :\\n\\n• la violation importante de ces Conditions ;\\n• une activité illégale ;\\n• une fraude ou un abus ;\\n• des menaces de sécurité ;\\n• un risque pour les autres utilisateurs ou l’infrastructure ;\\n• le non-paiement d’un service payant applicable ;\\n• des obligations légales.\\n\\nLorsque cela est approprié et raisonnablement possible, NatalNode peut donner un avis ou la possibilité de remédier à la violation."),
    translatedSection('19', 'Exclusions de garantie', "Dans la mesure maximale permise par la loi applicable, le Service est fourni « selon disponibilité ».\\n\\nNatalNode ne garantit pas :\\n\\n• que le Service sera toujours ininterrompu ;\\n• que chaque source de données tierce sera toujours disponible ;\\n• que toutes les informations saisies par les utilisateurs sont exactes ;\\n• qu’une interprétation astrologique prédira ou expliquera un résultat individuel ;\\n• que l’utilisation du Service produira un résultat personnel, professionnel, financier, sanitaire, relationnel ou autre déterminé.\\n\\nRien dans ces Conditions n’exclut les garanties ou droits des consommateurs qui ne peuvent légalement être exclus."),
    translatedSection('20', 'Limitation de responsabilité', "Dans la mesure maximale permise par la loi applicable, NatalNode et l’opérateur concerné ne seront pas responsables des dommages indirects, accessoires, spéciaux, consécutifs, exemplaires ou punitifs découlant de l’utilisation du Service lorsque cette exclusion est légalement permise.\\n\\nNatalNode n’est pas responsable des décisions que vous prenez uniquement sur la base d’une interprétation astrologique.\\n\\nPour les réclamations dont la responsabilité peut être limitée légalement, la responsabilité globale liée au Service ne dépassera pas le montant le plus élevé entre :\\n\\n• le montant que vous avez payé directement à NatalNode pour le Service au cours des 12 mois précédant l’événement à l’origine de la réclamation ; ou\\n• 100 USD.\\n\\nCette limitation ne s’applique pas lorsque la responsabilité ne peut légalement être exclue ou limitée, notamment les protections obligatoires des consommateurs ou autres droits auxquels il ne peut être renoncé.\\n\\nLe plafond monétaire final reste soumis à examen lorsque l’entité opérationnelle américaine et la juridiction compétente seront établies."),
    translatedSection('21', 'Indemnisation', "Dans la mesure permise par la loi applicable, vous acceptez d’indemniser et de garantir l’opérateur de NatalNode contre les réclamations de tiers résultant de :\\n\\n• Contenu utilisateur que vous soumettez illégalement ;\\n• votre violation importante de ces Conditions ;\\n• votre utilisation illégale des informations d’une autre personne ;\\n• votre atteinte aux droits d’une autre personne.\\n\\nCette disposition ne vous oblige pas à indemniser NatalNode pour une conduite dont la loi applicable rend NatalNode responsable."),
    translatedSection('22', 'Confidentialité', "La collecte et l’utilisation des informations personnelles par NatalNode sont décrites dans la Politique de confidentialité de NatalNode.\\n\\nLa Politique de confidentialité est une partie importante de votre compréhension du Service, mais elle ne vise pas à renoncer aux droits accordés par la législation applicable en matière de confidentialité."),
    translatedSection('23', 'Modifications de ces Conditions', "NatalNode peut mettre à jour ces Conditions lorsque le Service ou la loi applicable changent.\\n\\nLes modifications importantes seront communiquées de manière appropriée.\\n\\nSi la loi exige un accord affirmatif à une modification, cette modification ne vous liera pas simplement parce qu’une page a été mise à jour silencieusement.\\n\\nLa date d’entrée en vigueur identifie la version actuelle."),
    translatedSection('24', 'Droit applicable et litiges', "[GOVERNING_LAW_AND_FORUM_CLAUSE]\\n\\nCette disposition est intentionnellement différée jusqu’à l’établissement de l’entité opérationnelle et de la juridiction de production.\\n\\nAvant le lancement commercial public, elle doit être remplacée par une clause finale examinée au regard de :\\n\\n• l’État dans lequel l’entité opérationnelle américaine est constituée ;\\n• le véritable rattachement professionnel de l’opérateur ;\\n• les lois de protection des consommateurs applicables aux marchés cibles ;\\n• toute décision d’arbitrage ou de tribunal adoptée par le Product Owner.\\n\\nD’ici là, aucune juridiction fictive n’est indiquée.\\n\\nLes droits impératifs des consommateurs au titre de la loi applicable ne peuvent être abandonnés par ce marqueur."),
    translatedSection('25', 'Contact', "Support général :\\n\\n[SUPPORT_CONTACT_EMAIL]\\n\\nNotifications juridiques :\\n\\n[LEGAL_CONTACT_EMAIL]\\n\\nOpérateur :\\n\\n[OPERATOR_LEGAL_NAME]\\n[OPERATOR_ADDRESS]\\n\\nCes champs doivent être finalisés avant le lancement commercial public.")
  ],
  TERMS_SOURCE
);

